void usage(void) {
    printf("larimar %.*s\n", (int)(rt_str("0.3.0", 5)).len, (rt_str("0.3.0", 5)).ptr);
    fputs("\n", stdout);
    fputs("  larimar new <name>            create a project in a new folder\n", stdout);
    fputs("  larimar build [folder]        compile the project (larimar.toml) to an executable\n", stdout);
    fputs("  larimar run [folder] [-- args] build, then run it with the arguments\n", stdout);
    fputs("  larimar build --debug         with -g -O0 and the .lar lines, for a debugger (lldb, gdb, VS Code)\n", stdout);
    fputs("  larimar check [file|folder]   find the errors without generating C (--json for tools)\n", stdout);
    fputs("  larimar test [file|folder]... run the tests (tests/ by default; --only <text>, --no-sanitize)\n", stdout);
    fputs("  larimar lsp                   language server for editors (speaks LSP on stdin/stdout)\n", stdout);
    fputs("  larimar dap [--backend <lldb-dap>]  debugger for editors (DAP on stdin/stdout, over lldb-dap)\n", stdout);
    fputs("  larimar c <file.lar>          print the generated C of a file\n", stdout);
    fputs("  larimar <file.lar> -o <out.c> write the generated C of a file\n", stdout);
    fputs("\n", stdout);
}

